syntax:
class MyClass {
    // No user-provided default constructor
    int member;  // Will be zero-initialized if no default constructor is provided
};

MyClass obj;  // Default initialization: If MyClass has no user-provided or deleted default constructor, obj.member is zero-initialized at runtime.

class AnotherClass {
    AnotherClass() = default;  // User-provided (via = default), so default-initialized by calling this constructor
    int member;
};

// Implementation note: For classes without a user-provided constructor, the compiler implicitly generates zero-initialization code in the synthesized constructor.
